import zipfile, xml.etree.ElementTree as ET

path = '/home/jellypai/.claude/uploads/61a57fee-1202-45b5-94e0-8e44cfb81201/a042bd66-Agent_register_v3.xlsx'
ns = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'

with zipfile.ZipFile(path) as z:
    # Shared strings
    ss_xml = ET.fromstring(z.read('xl/sharedStrings.xml'))
    shared = []
    for si in ss_xml.findall(f'.//{{{ns}}}si'):
        t = ''.join(e.text or '' for e in si.iter(f'{{{ns}}}t'))
        shared.append(t)

    # Workbook rels to map rId -> filename
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels}

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb.findall(f'.//{{{ns}}}sheet')]

    def cell_val(c, shared):
        t = c.get('t', '')
        v_el = c.find(f'{{{ns}}}v')
        if v_el is None:
            return ''
        v = v_el.text or ''
        if t == 's':
            try: return shared[int(v)]
            except: return v
        if t == 'inlineStr':
            return ''.join(e.text or '' for e in c.iter(f'{{{ns}}}t'))
        return v

    def dump_sheet(name, rid, max_rows=60):
        target = rel_map.get(rid, '').replace('../', 'xl/../').lstrip('xl/../')
        fn = f'xl/{rel_map[rid].lstrip("/")}'.replace('xl/xl/', 'xl/')
        try:
            ws = ET.fromstring(z.read(fn))
        except:
            try:
                fn = 'xl/' + rel_map[rid]
                ws = ET.fromstring(z.read(fn))
            except Exception as e:
                return f"[could not read: {e}]"

        rows_out = []
        for row in ws.findall(f'.//{{{ns}}}row')[:max_rows]:
            cells = []
            for c in row.findall(f'{{{ns}}}c'):
                v = cell_val(c, shared)
                if v.strip():
                    ref = c.get('r', '')
                    cells.append(f'{ref}={repr(v[:80])}')
            if cells:
                rows_out.append(' | '.join(cells))
        return '\n'.join(rows_out)

    # Print key sheets
    key_sheets = ['Agent Register', 'Template', 'Executive Dashboard', 'Dashboard', 'Governance Controls Summary', 'Governance Lists', 'Change Log']
    for name, rid in sheets:
        if name in key_sheets:
            print(f'\n{"="*60}')
            print(f'SHEET: {name}')
            print('='*60)
            print(dump_sheet(name, rid, max_rows=80))

PYEOF
